INSERT INTO "public"."glossary" ("id", "term", "definition", "category", "related_terms", "example", "created_at", "updated_at", "is_active") VALUES
	('6bef0151-a99a-4cc9-827f-c627f09f4551', 'Scope 1 Emissions', 'Direct greenhouse gas emissions from sources that are owned or controlled by the organization. These include emissions from combustion of fuels in company vehicles, on-site heating, and industrial processes.', 'Scope', '{"Scope 2","Scope 3","Direct Emissions","GHG Protocol"}', 'A logistics company with 50 delivery vans that burn diesel would count those emissions as Scope 1.', '2026-07-24 11:04:06.679644+00', '2026-07-24 11:04:06.679644+00', true),
	('897603b1-ffe3-40cf-a8b2-a8bcc24f4a97', 'Scope 2 Emissions', 'Indirect greenhouse gas emissions from the generation of purchased electricity, steam, heating, and cooling consumed by the organization.', 'Scope', '{"Scope 1","Scope 3","Indirect Emissions","GHG Protocol"}', 'An office building purchasing electricity from the grid would include those emissions as Scope 2.', '2026-07-24 11:04:06.679644+00', '2026-07-24 11:04:06.679644+00', true),
	('e6763567-7922-4ab6-8aa8-be6882cff317', 'Scope 3 Emissions', 'All other indirect emissions that occur in the value chain of the reporting company. This includes business travel, employee commuting, waste disposal, and supply chain emissions.', 'Scope', '{"Scope 1","Scope 2","Value Chain Emissions","GHG Protocol"}', 'Emissions from employee air travel, contracted transport, and waste disposal are counted under Scope 3.', '2026-07-24 11:04:06.679644+00', '2026-07-24 11:04:06.679644+00', true),
	('bd781ee0-2e60-428e-a7ba-83a026591539', 'GHG Protocol', 'The Greenhouse Gas Protocol establishes comprehensive global standardized frameworks to measure and manage greenhouse gas emissions from private and public sector operations, value chains, and mitigation actions.', 'Methodology', '{"Scope 1","Scope 2","Scope 3","Corporate Standard"}', 'Companies use the GHG Protocol Corporate Standard to classify emissions into Scope 1, 2, and 3 categories.', '2026-07-24 11:04:06.679644+00', '2026-07-24 11:04:06.679644+00', true),
	('1fc57d15-f678-43a6-b1fd-9a95ca61b7c2', 'SECR', 'Streamlined Energy and Carbon Reporting is a UK government regulation requiring large companies to report their energy use and carbon emissions annually.', 'Reporting', '{CSRD,ISSB,"UK Regulation",Compliance}', 'UK companies with over 250 employees or £36 million turnover must comply with SECR requirements.', '2026-07-24 11:04:06.679644+00', '2026-07-24 11:04:06.679644+00', true),
	('da828a59-39db-43c4-8251-44fe6c5944de', 'CSRD', 'Corporate Sustainability Reporting Directive is an EU regulation requiring companies to disclose their environmental, social, and governance (ESG) impacts.', 'Reporting', '{SECR,ISSB,"ESRS E1","EU Regulation"}', 'Companies operating in the EU must comply with CSRD requirements and report on ESRS E1 climate standards.', '2026-07-24 11:04:06.679644+00', '2026-07-24 11:04:06.679644+00', true),
	('56f36546-838b-4d99-b5ee-51741932bef8', 'ISSB', 'International Sustainability Standards Board provides a global baseline for sustainability disclosures, helping investors compare companies on environmental performance.', 'Reporting', '{SECR,CSRD,"IFRS S2","Global Standards"}', 'ISSB standards are designed to be used alongside financial reporting for a complete picture of company performance.', '2026-07-24 11:04:06.679644+00', '2026-07-24 11:04:06.679644+00', true),
	('363db021-d2bd-4ec0-a5b1-2568f48a523b', 'DEFRA Factors', 'Department for Environment, Food & Rural Affairs conversion factors for calculating greenhouse gas emissions from various activities.', 'Methodology', '{"Conversion Factors","UK Government",CO2e,"Emissions Calculation"}', 'UK companies use DEFRA factors to convert fuel consumption (e.g., litres of diesel) into kg of CO2e.', '2026-07-24 11:04:06.679644+00', '2026-07-24 11:04:06.679644+00', true),
	('54c29583-341b-42b8-a7dd-8cf4624f138a', 'CO2e', 'Carbon dioxide equivalent is a standard unit for measuring and comparing greenhouse gas emissions based on their global warming potential.', 'Term', '{"Global Warming Potential","Greenhouse Gases",GWP}', 'Different greenhouse gases like methane are converted to CO2e based on their relative warming impact.', '2026-07-24 11:04:06.679644+00', '2026-07-24 11:04:06.679644+00', true),
	('77c349d3-66f4-41c6-9885-d94266233074', 'Net Zero', 'Net zero refers to achieving a balance between the greenhouse gases emitted into the atmosphere and those removed from it.', 'Sustainability', '{"Carbon Neutral","Carbon Offsetting",Decarbonization}', 'Companies with net zero targets must reduce their emissions as much as possible and offset any residual emissions.', '2026-07-24 11:04:06.679644+00', '2026-07-24 11:04:06.679644+00', true),
	('046a8280-b2cb-48f2-954e-fd21125ae9da', 'Carbon Footprint', 'The total amount of greenhouse gases generated by a person, organization, event, or product, measured in CO2e.', 'Term', '{CO2e,"Emissions Inventory",GHG,"Carbon Accounting"}', 'A company''s carbon footprint includes all Scope 1, 2, and 3 emissions across its value chain.', '2026-07-24 11:04:06.679644+00', '2026-07-24 11:04:06.679644+00', true),
	('efb6941b-f8c3-4a7b-b448-ee782a211a76', 'ESRS E1', 'European Sustainability Reporting Standard for Climate Change. Part of the CSRD framework requiring detailed climate-related disclosures.', 'Reporting', '{CSRD,"Climate Standards","EU Regulations"}', 'ESRS E1 requires companies to disclose climate transition plans, emissions targets, and Scope 1, 2, and 3 emissions.', '2026-07-24 11:04:06.679644+00', '2026-07-24 11:04:06.679644+00', true),
	('60255ece-c364-44ce-8664-c99c4d2d3e6b', 'AdBlue', 'A diesel exhaust fluid used to reduce NOx emissions in diesel engines. While it reduces other pollutants, it does not directly contribute to carbon emissions.', 'Term', '{Diesel,"Fleet Management","Vehicle Emissions"}', 'A fleet of heavy goods vehicles using AdBlue reduces NOx emissions but still needs to track diesel consumption for CO2e.', '2026-07-24 11:04:06.679644+00', '2026-07-24 11:04:06.679644+00', true),
	('479f46a2-ebe3-4ce1-902f-8417ee933b5d', 'Intensity Ratio', 'A metric that normalizes emissions by business activity, such as emissions per employee, per square meter, or per million pounds revenue.', 'Term', '{"SECR Reporting","Business Metrics","Performance Indicators"}', 'A retail chain reporting 2.5 tonnes CO2e per £1M revenue to show efficiency improvements year-over-year.', '2026-07-24 11:04:06.679644+00', '2026-07-24 11:04:06.679644+00', true),
	('9d7715c9-a8d7-4975-b4ee-cc098e90757b', 'Global Warming Potential (GWP)', 'A measure of how much energy the emissions of 1 tonne of a gas will absorb over a given period, relative to 1 tonne of CO2.', 'Methodology', '{CO2e,"Greenhouse Gases","Science-Based Targets"}', 'Methane has a GWP of 28, meaning it traps 28 times more heat than CO2 over 100 years.', '2026-07-24 11:04:06.679644+00', '2026-07-24 11:04:06.679644+00', true),
	('e6cb3132-8969-4255-8a3b-a4cb5e7b669f', 'Science-Based Targets', 'Emissions reduction targets that are aligned with the level of decarbonization required to keep global temperature increase within 1.5°C above pre-industrial levels.', 'Sustainability', '{"Net Zero",SBTi,"Climate Goals"}', 'A logistics company commits to reducing Scope 1 and 2 emissions by 50% by 2030 in line with SBTi criteria.', '2026-07-24 11:04:06.679644+00', '2026-07-24 11:04:06.679644+00', true),
	('6ef14139-3ecc-4e56-8d85-c102300f98e0', 'Carbon Neutral', 'Compensating for unavoidable emissions by purchasing carbon credits or supporting carbon removal projects.', 'Sustainability', '{"Net Zero","Carbon Offsetting","Carbon Credits"}', 'A company claiming carbon neutrality must reduce as much as possible and offset the rest.', '2026-07-24 11:04:06.679644+00', '2026-07-24 11:04:06.679644+00', true),
	('e1b805f2-6cd7-4f83-abfc-812c3b4c76b3', 'Emissions Trading Scheme (ETS)', 'A market-based approach to controlling pollution by providing economic incentives for achieving reductions in emissions of pollutants.', 'Term', '{"Carbon Pricing","Cap and Trade","EU ETS"}', 'The UK ETS and EU ETS require companies to hold allowances for each tonne of CO2e they emit.', '2026-07-24 11:04:06.679644+00', '2026-07-24 11:04:06.679644+00', true),
	('6a2b863d-a8db-4ad4-9e95-689022b9aa7d', 'Tonne of CO2e', 'A unit of measurement representing one metric tonne of carbon dioxide equivalent emissions.', 'Term', '{"Emissions Units","GHG Measurement","Carbon Accounting"}', 'A mid-sized company might emit 5,000 tonnes of CO2e annually across all scopes.', '2026-07-24 11:04:06.679644+00', '2026-07-24 11:04:06.679644+00', true),
	('e202e299-39a8-4703-b627-fe1950a13a0e', 'ESG', 'Environmental, Social, and Governance factors used to measure the sustainability and ethical impact of an investment in a company.', 'Term', '{"Sustainability Reporting",CSRD,"Investor Relations"}', 'Investors increasingly use ESG scores to assess climate risk and long-term company performance.', '2026-07-24 11:04:06.679644+00', '2026-07-24 11:04:06.679644+00', true);
